#!/usr/bin/env python3
"""Print the sections of entries.md for given entries (F-74 or S3). Mode 'now' prints from 'Now:' on."""
import sys, re
path = '/home/user/fortress-landing-31b/explorations/compile-ladder/climb-batch-31b/record-landing/entries.md'
text = open(path).read().split('\n')
mode = 'all'
args = sys.argv[1:]
if args and args[0] in ('now', 'all', 'hist'):
    mode = args.pop(0)
for a in args:
    if a.startswith('S'):
        pat = '## [' + a + '] '
    else:
        pat = '## ' + a + ', '
    out = []
    p = False
    for line in text:
        if line.startswith('## '):
            if p:
                break
            if line.startswith(pat):
                p = True
        if p:
            out.append(line)
    out = [l for l in out if l.strip()]
    if mode == 'now':
        try:
            i = out.index('Now:')
            out = [out[0]] + out[i:]
        except ValueError:
            pass
    elif mode == 'hist':
        out = [out[0]] + [l for l in out if l.startswith('- Written') or l.startswith('- Size')]
    print('\n'.join(out))
    print()

